#!/usr/bin/env bash
# Install a minimal LTR-only FriBidi and re-probe the wiliwili link.
#
# Two things happen here:
#   1. libfribidi.a is built from scripts/fribidi-stub/fribidi_stub.c, using the
#      REAL FriBidi headers copied out of the source tarball so the compiler
#      validates every signature against upstream. fribidi-config.h is normally
#      generated by configure (@PLACEHOLDER@ substitution); we substitute the
#      values by hand because configure cannot complete in this environment.
#   2. wiliwili is reconfigured with -DBUILTIN_NSP=OFF. The NSP forwarder target
#      shells out to hacbrewpack, which is a Linux ELF binary and dies on
#      Windows with "Exec format error" -- and because it is a dependency of
#      wiliwili.nro it was masking the entire main compile. NSP packaging is a
#      separate problem; the NRO is what proves the stack.
#
# Usage: build-fribidi-stub.sh <ascii-root>

set -uo pipefail

ROOT="${1:?ascii root required}"
SRC="$ROOT/third_party/src"
LOGDIR="$ROOT/build-logs"
FRI="$SRC/fribidi-1.0.12/lib"
mkdir -p "$LOGDIR"

export DEVKITPRO=/opt/devkitpro
export PORTLIBS_PREFIX="$DEVKITPRO/portlibs/switch"
export PATH="$DEVKITPRO/tools/bin:$DEVKITPRO/devkitA64/bin:$PORTLIBS_PREFIX/bin:$PATH"
INC="-I$PORTLIBS_PREFIX/include -I$DEVKITPRO/libnx/include"
export CPPFLAGS="-D__SWITCH__ -D_GNU_SOURCE $INC"
export CFLAGS="-O2 -Wall -march=armv8-a+crc+crypto -mtune=cortex-a57 -mtp=soft -fPIC -D__SWITCH__ -D_GNU_SOURCE $INC"

echo "=================== build libfribidi (LTR-only stub) ==================="
(
  set -e
  [ -d "$FRI" ] || { echo "no fribidi source at $FRI"; exit 1; }

  DEST="$PORTLIBS_PREFIX/include/fribidi"
  mkdir -p "$DEST"

  # fribidi-config.h: fribidi-config.h.in with the @PLACEHOLDER@s filled in.
  # Interface version 4 is what FriBidi 1.0.x advertises and what libass was
  # compiled against, so it must not drift.
  cat > "$DEST/fribidi-config.h" <<'EOF'
/* Generated by build-fribidi-stub.sh from fribidi-config.h.in (configure cannot run here). */
#ifndef FRIBIDI_CONFIG_H
#define FRIBIDI_CONFIG_H

#define FRIBIDI "fribidi"
#define FRIBIDI_NAME "GNU FriBidi"
#define FRIBIDI_BUGREPORT "https://github.com/fribidi/fribidi/issues/new"

#define FRIBIDI_VERSION "1.0.12"
#define FRIBIDI_MAJOR_VERSION 1
#define FRIBIDI_MINOR_VERSION 0
#define FRIBIDI_MICRO_VERSION 12
#define FRIBIDI_INTERFACE_VERSION 4
#define FRIBIDI_INTERFACE_VERSION_STRING "4"

/* The size of a `int', as computed by sizeof. */
#define FRIBIDI_SIZEOF_INT 4

/* Define if fribidi was built with MSVC */
/* #undef FRIBIDI_MSVC_BUILD */

#endif /* FRIBIDI_CONFIG_H */
EOF

  # Install the real public headers. Copying the whole lib/ set is deliberate:
  # fribidi.h pulls in some of them via quoted includes, and a partial copy is
  # more fragile than one extra internal header nobody includes.
  cp "$FRI"/*.h "$DEST"/
  echo "installed headers: $(ls -1 "$DEST"/*.h | wc -l)"

  # Build the stub and archive it.
  cd "$ROOT/scripts/fribidi-stub"
  aarch64-none-elf-gcc $CFLAGS $CPPFLAGS -c fribidi_stub.c -o fribidi_stub.o
  aarch64-none-elf-ar rcu libfribidi.a fribidi_stub.o
  aarch64-none-elf-ranlib libfribidi.a
  cp libfribidi.a "$PORTLIBS_PREFIX/lib/libfribidi.a"
  echo "archive size: $(stat -c%s "$PORTLIBS_PREFIX/lib/libfribidi.a")"
) > "$LOGDIR/build-fribidi-stub.log" 2>&1

if [ -f "$PORTLIBS_PREFIX/lib/libfribidi.a" ]; then
  echo ">>> OK libfribidi.a built"
  echo "=== symbols now defined (must include all 7 libass needs) ==="
  aarch64-none-elf-nm --defined-only "$PORTLIBS_PREFIX/lib/libfribidi.a" 2>/dev/null | grep ' T ' | awk '{print $3}' | sort
  echo ""
  echo "=== does it satisfy libass's undefined fribidi symbols? ==="
  MISS=0
  for s in $(aarch64-none-elf-nm -u "$PORTLIBS_PREFIX/lib/libass.a" 2>/dev/null | grep -o 'fribidi_[a-z_0-9]*' | sort -u); do
    if ! aarch64-none-elf-nm --defined-only "$PORTLIBS_PREFIX/lib/libfribidi.a" 2>/dev/null | grep -q " $s\$"; then
      echo "  STILL UNDEFINED: $s"; MISS=1
    fi
  done
  [ "$MISS" = "0" ] && echo "  all fribidi symbols required by libass are provided"
else
  echo ">>> FAIL fribidi stub -- last 25 lines:"
  tail -25 "$LOGDIR/build-fribidi-stub.log"
fi

echo ""
echo "=== rebuild the probe with BUILTIN_NSP=OFF ==="
# Patch the probe's cmake flags in place: NSP forwarder needs a Linux-only tool.
if grep -q 'DBUILTIN_NSP=ON' "$ROOT/scripts/probe-wiliwili-compile.sh"; then
  sed -i 's/-DBUILTIN_NSP=ON/-DBUILTIN_NSP=OFF/' "$ROOT/scripts/probe-wiliwili-compile.sh"
  echo "probe script: BUILTIN_NSP -> OFF"
fi
rm -rf "$ROOT/upstream/wiliwili/cmake-build-switch"
bash "$ROOT/scripts/probe-wiliwili-compile.sh" "$ROOT"
